import torch
import torch.nn as nn
from torch.utils.data import DataLoader, TensorDataset
import itertools

from .model import TASKS, ResidualMLP


# Baseline settings. Deliberately plain so they are easy to beat:
# plain SGD, constant learning rate, no dropout, no schedule, no augmentation.
LEARNING_RATE = 0.003
BATCH_SIZE = 256
EPOCHS = {"mnist": 30, "cifar10": 10, "imagenet32": 5}


# this function was generated by Claude. See conversation #2 in prompts.txt
def augment_with_flips(images: torch.Tensor, labels: torch.Tensor):
    """
    images: (B, C, H, W)
    labels: (B, ...) e.g. (B,) for class labels
    returns: images of shape (3B, C, H, W), labels of shape (3B, ...)
    """
    v_flipped = torch.flip(images, dims=[2])  # reverse rows (H axis)
    h_flipped = torch.flip(images, dims=[3])  # reverse columns (W axis)

    all_images = torch.cat([images, v_flipped, h_flipped], dim=0)
    all_labels = torch.cat([labels, labels, labels], dim=0)
    return all_images, all_labels



def augment_with_fade(images: torch.Tensor, labels: torch.Tensor):
    
    faded = images * 0.75

    all_images = torch.cat([images, faded], dim=0)
    all_labels = torch.cat([labels, labels], dim=0)

    return all_images, all_labels


# this function was generated by Claude. See conversation #3 in prompts.txt
def augment_with_color_perm(x: torch.Tensor, y: torch.Tensor, k: int, generator: any = None):
    """
    Augment a batch of RGB images with k random channel permutations each.
 
    For every image, k *distinct* permutations of the 3 channels are drawn
    (independently per image), excluding the identity so none of the new
    images duplicates the original. Since 3 channels have 3! = 6 orderings,
    5 of which are non-identity, k can be at most 5.
 
    Args:
        x: Tensor of shape (B, 3, H, W).
        y: Label tensor of shape (B, ...) (e.g. class ids (B,) or one-hot (B, N)).
        k: Number of new permuted versions per image (0 <= k <= 5).
        generator: Optional torch.Generator for reproducibility.
 
    Returns:
        x_out: (B + B*k, 3, H, W). The originals come first, followed by the
               new images grouped per source image (image 0's k versions,
               then image 1's, ...).
        y_out: (B + B*k, ...) labels aligned with x_out.
    """
    B, C, H, W = x.shape
    if C != 3:
        raise ValueError(f"Expected 3 channels, got {C}")
    if not 0 <= k <= 5:
        raise ValueError(f"k must be between 0 and 5, got {k}")
    if y.shape[0] != B:
        raise ValueError("x and y must have the same batch size")
    if k == 0:
        return x, y
 
    # The 5 non-identity permutations of (0, 1, 2) -> shape (5, 3)
    perms = torch.tensor(
        [p for p in itertools.permutations(range(3)) if p != (0, 1, 2)],
        device=x.device,
    )
 
    # For each image, pick k distinct permutations: random scores -> argsort -> take first k
    scores = torch.rand(B, 5, device=x.device, generator=generator)
    choice = scores.argsort(dim=1)[:, :k]            # (B, k)
    perm_idx = perms[choice]                         # (B, k, 3)
 
    # Gather channels: new[b, j, c] = x[b, perm_idx[b, j, c]]
    x_exp = x.unsqueeze(1).expand(B, k, C, H, W)
    idx = perm_idx[..., None, None].expand(B, k, C, H, W)
    x_new = x_exp.gather(2, idx).reshape(B * k, C, H, W)
 
    # Each image's k variants are contiguous, so labels are repeat-interleaved
    y_new = y.repeat_interleave(k, dim=0)
 
    return torch.cat([x, x_new], dim=0), torch.cat([y, y_new], dim=0)



def prepare(X, y=None):
    """Convert uint8 images (0-255) to floats in roughly [-1, 1]."""

    X_normed = (torch.as_tensor(X).float() / 255.0 - 0.5) / 0.5

    # assume testing if no y
    if y is None:
        return X_normed

    # X_normed, y = augment_with_flips(X_normed, y)
    # X_normed, y = augment_with_fade(X_normed, y)
    X_normed, y = augment_with_color_perm(X_normed, y, 2)

    return X_normed, y



